// Late-purchase fines (docs/reglas-negocio.md, RN-3.3 and RN-3.4).
// Fines are only generated by not buying shares on time.

import { diasEntre, mesesEntre, primerDiaDelMes, sumarMeses, type FechaISO } from '@/shared/domain/fechas';

// Configurable parameters (docs/reglas-negocio.md, section 10).
export interface ReglasDeMulta {
  diasDeGracia: number;
  multaPorDia: number;
  topeMensual: number;
}

export interface DetalleDeMulta {
  porMes: { mes: FechaISO; multa: number }[];
  total: number;
}

// RN-3.4: multa_mes = MIN(MAX(día − gracia, 0) × multa_por_día, tope).
export function multaDelMesEnCurso(dia: number, reglas: ReglasDeMulta): number {
  const diasDeMora = Math.max(dia - reglas.diasDeGracia, 0);
  return Math.min(diasDeMora * reglas.multaPorDia, reglas.topeMensual);
}

export interface DetalleDeMultaDelMes {
  monto: number;
  diasDeMora: number;
  // Days that add to the fine; they stop at the monthly cap.
  diasCobrados: number;
  topado: boolean;
}

// RN-3.4: each unpaid month adds the daily fine from the day after its grace
// days (day 11) until the monthly cap. A past month keeps adding until the
// cap; it is not charged the cap at once (Cris, 2026-10-27).
export function detalleDeMulta(params: { mes: FechaISO; hoy: FechaISO; reglas: ReglasDeMulta }): DetalleDeMultaDelMes {
  const { mes, hoy, reglas } = params;
  const finDeGracia = sumarDias(primerDiaDelMes(mes), reglas.diasDeGracia - 1);
  const diasDeMora = Math.max(diasEntre(finDeGracia, hoy), 0);
  const sinTope = diasDeMora * reglas.multaPorDia;
  // RN-3.4: whole days only; the day that crosses the cap is not counted.
  const diasHastaElTope = reglas.multaPorDia > 0 ? Math.floor(reglas.topeMensual / reglas.multaPorDia) : 0;
  return {
    monto: Math.min(sinTope, reglas.topeMensual),
    diasDeMora,
    diasCobrados: reglas.multaPorDia > 0 ? Math.min(diasDeMora, diasHastaElTope) : 0,
    topado: sinTope > reglas.topeMensual,
  };
}

export function multaDelMes(params: { mes: FechaISO; hoy: FechaISO; reglas: ReglasDeMulta }): number {
  return detalleDeMulta(params).monto;
}

function sumarDias(fecha: FechaISO, dias: number): FechaISO {
  const [anio, mes, dia] = fecha.split('-').map(Number);
  const d = new Date(Date.UTC(anio, mes - 1, dia + dias));
  return d.toISOString().slice(0, 10) as FechaISO;
}

// RN-3.4: the fine of every month from `primerMesPendiente`, the first month
// the shareholder has not bought, to the current month.
export function calcularMulta(params: {
  primerMesPendiente: FechaISO;
  hoy: FechaISO;
  reglas: ReglasDeMulta;
}): DetalleDeMulta {
  const { primerMesPendiente, hoy, reglas } = params;
  const meses = mesesEntre(primerMesPendiente, hoy);
  const porMes: { mes: FechaISO; multa: number }[] = [];
  for (let i = 0; i <= meses; i++) {
    const mes = sumarMeses(primerMesPendiente, i);
    porMes.push({ mes, multa: multaDelMes({ mes, hoy, reglas }) });
  }
  return { porMes, total: porMes.reduce((suma, m) => suma + m.multa, 0) };
}
